const j = $input.first().json;

// The website chat posts { sessionId, message, channel } to the webhook; a
// WhatsApp message arrives from Read Message (or Describe Photo For Agent) as
// { from, text }, keyed by the sender's number.
const b = j.body ?? (j.from ? { sessionId: j.from, message: j.text, channel: 'whatsapp' } : {});

// Trim and cap the message so one visitor cannot send a novel to the model.
// An empty message is treated as a greeting rather than rejected.
const message = String(b.message ?? '').trim().slice(0, 2000) || 'Hi';

// Channel decides the reply style; anything unknown is treated as web chat.
const channel = ['web', 'whatsapp', 'email'].includes(b.channel) ? b.channel : 'web';

// Test runs (the 30-case test set) behave exactly the same, except that
// escalations are logged but never reach Slack or a customer's inbox.
const test = b.test === true;

// One memory per conversation. Prefix with the channel so a web session and
// a WhatsApp number can never share history; fall back to the execution id,
// never a constant, so anonymous visitors are not pooled together.
const raw = String(b.sessionId ?? '').trim().slice(0, 100).replace(/[^A-Za-z0-9_+.:-]/g, '');
const sessionId = `${test ? 'test:' : ''}${channel}:${raw || 'anon-' + $execution.id}`;

return [{ json: { message, channel, test, sessionId } }];

// The agent node continues on error, so a failure still gets a polite reply
// and raises a Slack alert instead of leaving the customer hanging.
const j = $input.first().json;
const reply = String(j.output ?? '').trim();

// Which tools ran, and whether the request went for approval or to a person.
// The test set scores these, so the outcome is read from what actually
// happened, not from the wording of the reply.
const steps = j.intermediateSteps ?? [];
const tools = [...new Set(steps.map(s => s.action?.tool).filter(Boolean))];
const seen = steps.map(s => JSON.stringify(s.observation ?? '')).join(' ');
const escalation = /\bapproval\b/.test(seen.match(/decision\\?":\s*\\?"(\w+)/)?.[1] ?? '') ? 'approval'
  : /handover/.test(seen.match(/decision\\?":\s*\\?"(\w+)/)?.[1] ?? '') ? 'handover' : null;

return [{ json: {
  reply: reply || 'Sorry, I could not answer that just now. A member of the Fernhill team will follow up.',
  failed: !reply,
  error: j.error ? String(j.error.message ?? j.error).slice(0, 500) : '',
  tools,
  escalation,
}}];

