// Fixed rules: the AI only PROPOSES an escalation. This code decides what
// actually happens, so a confused or manipulated model can never skip a person.
const req = $('Team Request In').first().json;
const found = $input.all().map(i => i.json).find(j => j.fields || j.id);
const order = found ? (found.fields ?? found) : null;

const MONEY = ['refund', 'replacement', 'exchange', 'cancellation', 'price_adjustment', 'discount'];
const type = String(req.request_type || 'handover').toLowerCase();
const needsMoney = MONEY.includes(type);

let decision, status, toAgent;
if (needsMoney && order) {
  decision = 'Needs Approval';
  status = 'Waiting Approval';
  toAgent = `Logged as case ${req.session_id}. A team member must approve this ${type.replace('_', ' ')} request; ` +
            `the customer will get an email at the address on the order within one working day. Do not promise the outcome.`;
} else {
  // Handover: asked for, or a money request we could not tie to a verified order.
  decision = 'Handed Over';
  status = 'Open';
  toAgent = needsMoney
    ? `Could not verify the order, so this was passed to a team member as case ${req.session_id}. Tell the customer a person will reply within one working day.`
    : `Handed to a team member as case ${req.session_id}. Tell the customer a person will reply within one working day.`;
}

const categories = ['Order Status', 'Shipping', 'Return', 'Refund', 'Wrong or Damaged Item', 'Product Question', 'Complaint', 'Other'];
const category = categories.includes(req.category) ? req.category : 'Other';

return [{ json: {
  caseId: req.session_id,
  sessionId: req.session_id,
  channel: req.channel || 'Web Chat',
  requestType: type,
  orderNumber: order ? order['Order Number'] : String(req.order_number || ''),
  customerEmail: order ? order['Customer Email'] : '',
  orderTotal: order ? order['Order Total'] : null,
  orderStatus: order ? order['Status'] : '',
  category,
  details: `${type.toUpperCase()}: ${req.reason || ''}\nSummary: ${req.summary || ''}`.slice(0, 2000),
  decision, status, toAgent,
  verified: Boolean(order),
  test: String(req.test) === 'true',
}}];

